pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1 wei, 1000 ether);
        SelfDestructer helper = new SelfDestructer();
        vm.deal(address(c), amount);
        c.forward(address(helper), "");
        assertTrue(address(c).balance == amount);
    }
}

contract SelfDestructer {
    fallback() external payable {
        selfdestruct(payable(msg.sender));
    }
}

