pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes calldata data) public {
        Counting target = new Counting();
        vm.prank(address(0xdead));
        c.forward(address(target), data);
        assertTrue(target.calls() == 1);
    }
}

contract Counting {
    uint256 public calls;
    fallback() external payable { calls++; }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 selector, bytes memory data) public {
        // choose between a reverting callee and a plain (empty-code) address
        address callee = selector % 2 == 0 ? address(new Reverter()) : address(0xDEAD);
        bool ok;
        try c.forward(callee, data) { ok = true; } catch { ok = false; }
        // General rule: whenever the callee's call reverts, forward must revert too.
        // On a Reverter callee this always holds for P; M returns ok=true and fails.
        if (selector % 2 == 0) {
            assertTrue(ok == false);
        } else {
            assertTrue(ok == true);
        }
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
